<ScrollStack
  class="rounded-xl border border-border p-3"
  direction="horizontal"
  snap={ true }
  perView="auto"
  itemMin="14rem"
  itemMax="20rem"
  gap="0.75rem">
  <scroll-stack-item>
    <div class="h-40 rounded-lg bg-brand-tint p-4">\u2026</div>
  </scroll-stack-item>
  \u2026
</ScrollStack>

// A fixed count instead: perView={ 3 } divides the port three ways.`,XG=`// snap={ true } and snap="center" are MANDATORY; snap="proximity" is the
